export async function loadGeneratedArticleBody(shard: number, slug: string) {
  const loader = bodyLoaders[shard as keyof typeof bodyLoaders];
  if (!loader) return null;
  const bodyModule = await loader();
  return (bodyModule.default as Record<string, string>)[slug] ?? null;
}
